#![allow(dead_code)]
#[path="../handheld/src/margin.rs"]mod margin;
use margin::*;
struct Fake{requested:u8,applied:u8,pending:bool,valid:bool,online:bool,ready:bool,result:u8,sequence:u8,core:u32,version:u32,magic:u32,build:u32,ops:usize,fail:usize,writes:Vec<(u32,u32)>,reject:u8,extra:u32}
impl Default for Fake{fn default()->Self{Self{requested:20,applied:20,pending:false,valid:true,online:true,ready:true,result:2,sequence:7,core:0x4d425631,version:0x10000,magic:MAGIC,build:BUILD,ops:0,fail:0,writes:vec![],reject:0,extra:0}}}
impl Fake{fn status(&self)->u32{self.applied as u32|((self.pending as u32)<<7)|((self.valid as u32)<<8)|((self.online as u32)<<9)|((self.ready as u32)<<10)|((self.result as u32)<<16)|((self.sequence as u32)<<24)|self.extra}fn apply(&mut self){self.applied=self.requested;self.pending=false;self.valid=true;self.ready=true;self.sequence=self.sequence.wrapping_add(1);self.result=2;}}
impl Bus for Fake{fn read(&mut self,off:u32)->Result<u32,()>{self.ops+=1;if self.ops==self.fail{return Err(())}Ok(match off{0=>self.core,4=>self.version,0x184=>self.build,0x08c=>self.magic,0x084=>self.requested as u32,0x088=>self.status(),_=>panic!("unexpected read{off:x}")})}fn write(&mut self,off:u32,value:u32)->Result<(),()>{self.ops+=1;assert_eq!(off,0x84);assert!(value<=80);self.writes.push((off,value));if self.reject!=0{self.result=self.reject}else{self.requested=value as u8;self.pending=true;self.ready=false;self.result=1;}if self.ops==self.fail{Err(())}else{Ok(())}}}
fn begin(key:u8)->Controller{let mut c=Controller::new();assert_eq!(c.request(key),Ok(true));c}
#[test]fn only_vblank_application_sequence_confirms_success(){let mut c=begin(b'=');let mut b=Fake::default();assert_eq!(c.step(&mut b),None);assert_eq!(b.writes,[(0x84,40)]);assert_eq!(c.step(&mut b),None);b.applied=40;b.pending=false;b.ready=true;assert_eq!(c.step(&mut b),None);b.sequence+=1;assert_eq!(c.step(&mut b).unwrap().outcome,Outcome::Applied);}
#[test]fn query_is_read_only_and_can_report_startup_invalid_pending(){let mut c=begin(b'h');let mut b=Fake{pending:true,valid:false,ready:false,result:0,..Default::default()};let r=c.step(&mut b).unwrap();assert_eq!(r.outcome,Outcome::Status);assert_eq!(r.observed.unwrap().applied_valid(),None);assert!(!r.write_attempted);assert!(b.writes.is_empty());}
#[test]fn old_or_wrong_images_never_receive_writes(){for field in 0..4{let mut c=begin(b']');let mut b=Fake::default();match field{0=>b.core=0,1=>b.version=0x20000,2=>b.build-=1,_=>b.magic=0};assert_eq!(c.step(&mut b).unwrap().outcome,Outcome::Identity);assert!(b.writes.is_empty());}}
#[test]fn startup_pending_offline_and_notready_are_rejected_before_write(){for condition in 0..3{let mut c=begin(b']');let mut b=Fake::default();match condition{0=>b.pending=true,1=>b.online=false,_=>b.ready=false};assert_eq!(c.step(&mut b).unwrap().outcome,Outcome::Busy);assert!(b.writes.is_empty());}}
#[test]fn unchanged_edge_clamps_do_not_submit_redundant_requests(){for(key,value)in[(b'[',0),(b'{',0),(b']',80),(b'}',80),(b'|',20),(b'=',40)]{let mut c=begin(key);let mut b=Fake{requested:value,applied:value,..Default::default()};assert_eq!(c.step(&mut b).unwrap().outcome,Outcome::Unchanged);assert!(b.writes.is_empty());}}
#[test]fn delta_uses_actual_lastaccepted_requested_not_a_cached_default(){let mut c=begin(b']');let mut b=Fake{requested:63,applied:63,..Default::default()};assert_eq!(c.step(&mut b),None);assert_eq!(b.writes,[(0x84,64)]);}
#[test]fn sequence_wrap_is_supported(){let mut c=begin(b'=');let mut b=Fake{sequence:255,..Default::default()};c.step(&mut b);b.apply();assert_eq!(c.step(&mut b).unwrap().outcome,Outcome::Applied);}
#[test]fn matching_receipt_offline_or_notready_is_not_applied(){for offline in [true,false]{let mut c=begin(b'=');let mut b=Fake::default();c.step(&mut b);b.apply();if offline{b.online=false}else{b.ready=false}assert!(c.step(&mut b).is_none());b.online=true;b.ready=true;assert_eq!(c.step(&mut b).unwrap().outcome,Outcome::Applied);}}
#[test]fn all_thirteen_initial_and_poll_io_failure_sites_are_terminal(){for fail in 1..=13{let mut c=begin(b'=');let mut b=Fake{fail,..Default::default()};let first=c.step(&mut b);let r=if let Some(r)=first{r}else{b.apply();c.step(&mut b).unwrap()};assert_eq!(r.outcome,Outcome::Io,"op{fail}");assert!(r.observed.is_none());assert_eq!(r.write_attempted,fail>=7);let n=b.ops;assert_eq!(c.step(&mut b),None);assert_eq!(b.ops,n);assert!(b.writes.len()<=1);}}
#[test]fn ambiguous_write_is_not_retried_or_rolled_back(){let mut c=begin(b'=');let mut b=Fake{fail:7,..Default::default()};let r=c.step(&mut b).unwrap();assert_eq!(r.outcome,Outcome::Io);assert!(r.write_attempted);assert_eq!(b.requested,40);assert!(b.pending);assert_eq!(b.writes,[(0x84,40)]);}
#[test]fn rejected_busy_or_range_report_held_request(){for(code,outcome)in[(3,Outcome::Range),(4,Outcome::Busy)]{let mut c=begin(b'=');let mut b=Fake{reject:code,..Default::default()};assert_eq!(c.step(&mut b),None);let r=c.step(&mut b).unwrap();assert_eq!(r.outcome,outcome);assert_eq!(r.target,Some(40));assert_eq!(r.observed.unwrap().requested,20);}}
#[test]fn interleaved_rejection_result_does_not_override_sequence_and_value(){for code in [3,4]{let mut c=begin(b'=');let mut b=Fake::default();c.step(&mut b);b.result=code;assert_eq!(c.step(&mut b),None);b.apply();b.result=code;assert_eq!(c.step(&mut b).unwrap().outcome,Outcome::Applied);}}
#[test]fn link_reset_reports_uncertainty_without_retry(){let mut c=begin(b'=');let mut b=Fake::default();c.step(&mut b);b.valid=false;b.online=false;b.result=5;let r=c.step(&mut b).unwrap();assert_eq!(r.outcome,Outcome::LinkReset);assert_eq!(r.observed.unwrap().applied_valid(),None);assert_eq!(b.writes.len(),1);}
#[test]fn timeout_clears_observation_and_never_adds_writes(){let mut c=begin(b'=');let mut b=Fake::default();c.step(&mut b);let r=loop{if let Some(r)=c.step(&mut b){break r}};assert_eq!(r.outcome,Outcome::Timeout);assert!(r.observed.is_none());assert_eq!(b.writes.len(),1);}
#[test]fn explicit_deadline_expires_even_without_any_device_access(){let mut c=begin(b'=');let r=c.expire().unwrap();assert_eq!(r.outcome,Outcome::Timeout);assert!(!r.write_attempted);assert!(r.observed.is_none());assert!(c.expire().is_none());}
#[test]fn rapid_command_is_rejected_locally_without_replacing_inflight_target(){let mut c=begin(b'=');assert_eq!(c.request(b'[').unwrap_err().outcome,Outcome::LocalBusy);let mut b=Fake::default();c.step(&mut b);assert_eq!(b.writes,[(0x84,40)]);b.apply();assert_eq!(c.step(&mut b).unwrap().key,b'=');assert_eq!(c.request(b'['),Ok(true));}
#[test]fn unknown_bits_values_and_results_fail_closed(){for extra in [1<<11,1<<20,6<<16]{let mut c=begin(b'=');let mut b=Fake{extra,..Default::default()};assert_eq!(c.step(&mut b).unwrap().outcome,Outcome::InvalidStatus);assert!(b.writes.is_empty());}assert!(Observation::decode(81,0).is_err());assert!(Observation::decode(20,81).is_err());}
#[test]fn core_replacement_during_poll_stops_without_writes_to_replacement(){let mut c=begin(b'=');let mut b=Fake::default();c.step(&mut b);b.build-=1;let r=c.step(&mut b).unwrap();assert_eq!(r.outcome,Outcome::Identity);assert!(r.observed.is_none());assert_eq!(b.writes.len(),1);}
#[test]fn idle_ticks_are_free_and_calls_have_at_most_seven_transactions(){let mut c=Controller::new();let mut b=Fake::default();assert_eq!(c.step(&mut b),None);assert_eq!(b.ops,0);c.request(b'=');for n in 0..3{let before=b.ops;if n==2{b.apply();}c.step(&mut b);assert!(b.ops-before<=7);}}
#[test]fn changed_request_and_wrong_applied_value_are_not_success(){let mut c=begin(b'=');let mut b=Fake::default();c.step(&mut b);b.requested=30;assert_eq!(c.step(&mut b).unwrap().outcome,Outcome::Changed);let mut c=begin(b'=');let mut b=Fake::default();c.step(&mut b);b.apply();b.applied=39;assert_eq!(c.step(&mut b).unwrap().outcome,Outcome::Mismatch);}
#[test]fn host_controller_storage_is_small_not_a_target_stack_proof(){println!("HOST_CONTROLLER_BYTES={}",std::mem::size_of::<Controller>());assert!(std::mem::size_of::<Controller>()<=64);assert!(std::mem::size_of::<Report>()<=64);}
